{"path": "/app/maximal_square.py", "content": "import numpy as np
from numba import jit

@jit(nopython=True)
def maximal_square(matrix: np.ndarray) -> int:
    # matrix only contains 0s and 1s
    rows = matrix.shape[0]
    cols = matrix.shape[1]

    # Use a 1D array for DP state
    dp = np.zeros(cols + 1, dtype=np.int32)
    maxsqlen = 0

    for i in range(rows):
        prev = 0
        for j in range(cols):
            temp = dp[j + 1]
            if matrix[i, j] == 1:
                dp[j + 1] = min(min(dp[j], prev), dp[j + 1]) + 1
                maxsqlen = max(maxsqlen, dp[j + 1])
            else:
                dp[j + 1] = 0
            prev = temp

    return maxsqlen * maxsqlen
"}

