{"path": "/app/ars.R", "content": "# Adaptive Rejection Sampling (ARS) Implementation
# Based on Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for Gibbs sampling.
# Journal of the Royal Statistical Society: Series C (Applied Statistics), 41(2), 337-348.

# Main function: ars
# Implements the adaptive rejection sampler for log-concave densities
# Input:
#   log_density: function that computes log of unnormalized density (vectorized)
#   domain: vector of length 2, lower and upper bounds of support
#   n_samples: number of samples to generate
#   max_iter: maximum number of iterations for adaptive envelope construction
#   tol: tolerance for convergence in log-concavity check
# Output:
#   vector of samples from the target distribution

ars <- function(log_density, domain, n_samples, max_iter = 1000, tol = 1e-6) {
  # Input validation
  if (missing(log_density) || !is.function(log_density)) {
    stop("log_density must be a function")
  }
  if (missing(domain) || !is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2")
  }
  if (domain[1] >= domain[2]) {
    stop("domain[1] must be less than domain[2]")
  }
  if (missing(n_samples) || !is.numeric(n_samples) || length(n_samples) != 1 || n_samples < 1) {
    stop("n_samples must be a positive integer")
  }
  if (missing(max_iter) || !is.numeric(max_iter) || length(max_iter) != 1 || max_iter < 1) {
    stop("max_iter must be a positive integer")
  }
  if (missing(tol) || !is.numeric(tol) || length(tol) != 1 || tol <= 0) {
    stop("tol must be a positive number")
  }

  # Initialize the envelope
  x <- seq(domain[1], domain[2], length.out = 100)
  log_f <- log_density(x)

  # Check for log-concavity
  if (!is.log_concave(log_f, x, tol)) {
    warning("Density is not log-concave. ARS may not converge properly.")
  }

  # Initialize the envelope: piecewise linear upper bound
  # Start with a single chord between endpoints
  x1 <- domain[1]
  x2 <- domain[2]
  f1 <- log_density(x1)
  f2 <- log_density(x2)

  # Store the envelope as a list of chords
  # Each chord is a list with x1, x2, f1, f2
  chords <- list(c(x1, x2, f1, f2))

  # Adaptive envelope construction
  for (iter in 1:max_iter) {
    # Check if envelope is sufficiently tight
    if (is.envelope.tight(chords, log_density, domain, tol)) {
      break
    }

    # Find the point of maximum gap between envelope and density
    # Use a fine grid to find the maximum gap
    x_grid <- seq(domain[1], domain[2], length.out = 1000)
    log_f_grid <- log_density(x_grid)
    envelope_grid <- evaluate.envelope(chords, x_grid)

    # Find the point with maximum gap
    gaps <- envelope_grid - log_f_grid
    max_gap_idx <- which.max(gaps)
    x_new <- x_grid[max_gap_idx]

    # If gap is small enough, stop
    if (gaps[max_gap_idx] < tol) {
      break
    }

    # Add new chord at x_new
    f_new <- log_density(x_new)

    # Find the chord that contains x_new
    chord_idx <- which(sapply(chords, function(c) c[1] <= x_new && x_new <= c[2]))
    if (length(chord_idx) == 0) {
      stop("Could not find chord containing new point")
    }
    chord_idx <- chord_idx[1]  # Take first (should be only one)

    # Split the chord into two
    old_chord <- chords[[chord_idx]]
    chords[[chord_idx]] <- list(old_chord[1], x_new, old_chord[3], f_new)
    chords[[length(chords) + 1]] <- list(x_new, old_chord[2], f_new, old_chord[4])
  }

  # Generate samples using rejection sampling
  samples <- numeric(n_samples)
  rejected <- 0

  for (i in 1:n_samples) {
    while (TRUE) {
      # Sample from the envelope
      # First, choose a chord at random with probability proportional to its length
      chord_lengths <- sapply(chords, function(c) c[2] - c[1])
      chord_probs <- chord_lengths / sum(chord_lengths)
      chord_idx <- sample(length(chords), 1, prob = chord_probs)

      # Sample uniformly from the chosen chord
      chord <- chords[[chord_idx]]
      x <- runif(1, chord[1], chord[2])

      # Evaluate the envelope at x
      envelope_value <- evaluate.envelope(chords, x)

      # Evaluate the target density at x
      target_value <- log_density(x)

      # Accept with probability exp(target_value - envelope_value)
      if (runif(1) < exp(target_value - envelope_value)) {
        samples[i] <- x
        break
      } else {
        rejected <- rejected + 1
      }
    }
  }

  # Return samples
  return(samples)
}

# Helper function: check if a function is log-concave
# Uses second-order finite differences
is.log_concave <- function(log_f, x, tol = 1e-6) {
  # Compute first differences
  df <- diff(log_f) / diff(x)

  # Compute second differences
  d2f <- diff(df) / diff(x[-length(x)])

  # Check if second differences are non-positive
  # If any second difference is positive, the function is not log-concave
  if (any(d2f > tol)) {
    return(FALSE)
  }
  return(TRUE)
}

# Helper function: evaluate the envelope at a point
# The envelope is piecewise linear
evaluate.envelope <- function(chords, x) {
  # Handle vectorized x
  if (is.vector(x)) {
    result <- numeric(length(x))
    for (i in seq_along(x)) {
      xi <- x[i]
      # Find the chord that contains xi
      chord_idx <- which(sapply(chords, function(c) c[1] <= xi && xi <= c[2]))
      if (length(chord_idx) == 0) {
        stop("x not in any chord")
      }
      chord_idx <- chord_idx[1]  # Take first
      chord <- chords[[chord_idx]]
      # Linear interpolation
      result[i] <- chord[3] + (xi - chord[1]) * (chord[4] - chord[3]) / (chord[2] - chord[1])
    }
    return(result)
  } else {
    # Handle scalar x
    chord_idx <- which(sapply(chords, function(c) c[1] <= x && x <= c[2]))
    if (length(chord_idx) == 0) {
      stop("x not in any chord")
    }
    chord_idx <- chord_idx[1]
    chord <- chords[[chord_idx]]
    return(chord[3] + (x - chord[1]) * (chord[4] - chord[3]) / (chord[2] - chord[1]))
  }
}

# Helper function: check if envelope is tight enough
is.envelope.tight <- function(chords, log_density, domain, tol = 1e-6) {
  # Sample a fine grid
  x_grid <- seq(domain[1], domain[2], length.out = 1000)
  log_f_grid <- log_density(x_grid)
  envelope_grid <- evaluate.envelope(chords, x_grid)

  # Compute maximum gap
  gaps <- envelope_grid - log_f_grid
  max_gap <- max(gaps)

  # If maximum gap is below tolerance, envelope is tight
  return(max_gap < tol)
}

# Test function
# Performs formal testing with known distributions
# Outputs: "TEST_NAME: PASS" or "TEST_NAME: FAIL" with mean and std

test <- function() {
  # Test 1: Standard normal distribution
  cat("Testing ARS on standard normal distribution...\n")
  set.seed(123)
  log_density_normal <- function(x) -0.5 * x^2 - 0.5 * log(2 * pi)
  samples_normal <- ars(log_density_normal, domain = c(-5, 5), n_samples = 10000)

  # Expected mean and std for standard normal
  expected_mean <- 0
  expected_std <- 1

  # Compute sample mean and std
  sample_mean <- mean(samples_normal)
  sample_std <- sd(samples_normal)

  # Check if within reasonable tolerance
  tolerance <- 0.05
  if (abs(sample_mean - expected_mean) < tolerance && abs(sample_std - expected_std) < tolerance) {
    cat("TEST_NORMAL: PASS\n")
  } else {
    cat("TEST_NORMAL: FAIL\n")
  }
  cat("  Mean: ", sample_mean, ", Std: ", sample_std, " (expected: ", expected_mean, ", ", expected_std, ")\n\n")

  # Test 2: Exponential distribution with rate 1
  cat("Testing ARS on exponential distribution (rate=1)...\n")
  set.seed(123)
  log_density_exp <- function(x) -x  # log of exp(-x) for x >= 0
  samples_exp <- ars(log_density_exp, domain = c(0, 10), n_samples = 10000)

  # Expected mean and std for exponential(1)
  expected_mean <- 1
  expected_std <- 1

  # Compute sample mean and std
  sample_mean <- mean(samples_exp)
  sample_std <- sd(samples_exp)

  # Check if within reasonable tolerance
  if (abs(sample_mean - expected_mean) < tolerance && abs(sample_std - expected_std) < tolerance) {
