{"path": "/app/agent.py", "content": "import numpy as np
import torch


class Agent:
    def __init__(self):
        # Use a simple linear policy: action = sign(w @ obs)
        # Weights chosen from empirical testing: [0, 0, 10, 1]
        self.weights = np.array([0, 0, 10, 1], dtype=np.float32)

    def select_action(self, current_observation):
        # Convert observation to float32 for consistency
        obs = np.array(current_observation, dtype=np.float32)
        # Compute dot product and return action (0 or 1)
        return int(np.dot(self.weights, obs) > 0)

    def save(self, directory):
        # Save weights as a single NumPy file
        np.save(f"{directory}/weights.npy", self.weights)

    def load(self, directory):
        # Load weights from directory
        self.weights = np.load(f"{directory}/weights.npy")"}

