{"path": "/app/extract.js", "content": "/**
 * Extracts memory values from a compiled C binary and outputs them as a JSON object.
 * Usage: node extract.js /app/a.out > out.json
 */

const fs = require('fs');
const path = require('path');

// ELF constants
const ELF_MAGIC = 0x464c457f; // 0x7f 0x45 0x4c 0x46
const ELFCLASS64 = 2;
const ELFDATA2LSB = 1; // Little-endian

// Parse ELF header
function parseELFHeader(buffer) {
  const header = {};
  header.magic = buffer.readUInt32BE(0);
  header.class = buffer.readUInt8(4);
  header.data = buffer.readUInt8(5);
  header.version = buffer.readUInt8(6);
  header.osabi = buffer.readUInt8(7);
  header.abiversion = buffer.readUInt8(8);
  header.type = buffer.readUInt16BE(16);
  header.machine = buffer.readUInt16BE(18);
  header.version = buffer.readUInt32BE(20);
  header.entry = buffer.readUInt64BE(24);
  header.phoff = buffer.readUInt64BE(32);
  header.shoff = buffer.readUInt64BE(40);
  header.flags = buffer.readUInt32BE(48);
  header.ehsize = buffer.readUInt16BE(50);
  header.phentsize = buffer.readUInt16BE(52);
  header.phnum = buffer.readUInt16BE(54);
  header.shentsize = buffer.readUInt16BE(56);
  header.shnum = buffer.readUInt16BE(58);
  header.shstrndx = buffer.readUInt16BE(60);

  return header;
}

// Parse program header
function parseProgramHeader(buffer, offset) {
  const phdr = {};
  phdr.type = buffer.readUInt32BE(offset);
  phdr.offset = buffer.readUInt64BE(offset + 8);
  phdr.vaddr = buffer.readUInt64BE(offset + 16);
  phdr.paddr = buffer.readUInt64BE(offset + 24);
  phdr.filesz = buffer.readUInt64BE(offset + 32);
  phdr.memsz = buffer.readUInt64BE(offset + 40);
  phdr.flags = buffer.readUInt64BE(offset + 48);
  phdr.align = buffer.readUInt64BE(offset + 56);

  return phdr;
}

// Extract memory values from the binary
function extractMemoryValues(binaryPath) {
  const buffer = fs.readFileSync(binaryPath);
  const header = parseELFHeader(buffer);

  // Validate ELF header
  if (header.magic !== ELF_MAGIC) {
    throw new Error('Invalid ELF magic');
  }

  if (header.class !== ELFCLASS64) {
    throw new Error('Only 64-bit ELF files are supported');
  }

  if (header.data !== ELFDATA2LSB) {
    throw new Error('Only little-endian ELF files are supported');
  }

  const phoff = header.phoff;
  const phnum = header.phnum;
  const phentsize = header.phentsize;

  const memory = {};

  // Parse program headers
  for (let i = 0; i < phnum; i++) {
    const offset = phoff + i * phentsize;
    const phdr = parseProgramHeader(buffer, offset);

    // Skip non-loadable segments
    if (phdr.type !== 1) { // PT_LOAD
      continue;
    }

    // Calculate the virtual address base
    const vaddr = phdr.vaddr;

    // Read the segment data
    const fileData = buffer.slice(phdr.offset, phdr.offset + phdr.filesz);

    // Extract 32-bit little-endian words
    for (let j = 0; j < fileData.length; j += 4) {
      const word = fileData.readUInt32LE(j);
      const addr = vaddr + j;
      memory[addr.toString()] = word;
    }
  }

  return memory;
}

// Main function
function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    console.error('Usage: node extract.js <binary-path>');
    process.exit(1);
  }

  const binaryPath = args[0];

  try {
    const memory = extractMemoryValues(binaryPath);
    console.log(JSON.stringify(memory, null, 2));
  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

main();
"}

{"path": "server.js", "content": "const express = require('express');
const app = express();
const port = 3000;

// Middleware to parse query parameters
app.use(express.json());

// Function to calculate nth Fibonacci number
function fibonacci(n) {
  if (n <= 0) return 0;
  if (n === 1) return 1;

  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
}

// GET /fib endpoint
app.get('/fib', (req, res) => {
  // Get the 'n' parameter from query string
  const nParam = req.query.n;

  // Check if parameter is provided
  if (!nParam) {
    return res.status(400).json({ error: 'Query parameter n is required' });
  }

  // Parse the parameter to integer
  const n = parseInt(nParam, 10);

  // Check if parsing was successful
  if (isNaN(n)) {
    return res.status(400).json({ error: 'Query parameter n must be an integer' });
  }

  // Check if n is negative
  if (n < 0) {
    return res.status(400).json({ error: 'Query parameter n must be non-negative' });
  }

  // Calculate and return the result
  const result = fibonacci(n);
  res.json({ result });
});

// Start the server
app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});
"}

