    return occ

def is_legal_slide(prev_state, next_state):
    # Check if next_state is a valid slide from prev_state
    prev_occ=get_piece_cells(prev_state)
    next_occ=get_piece_cells(next_state)
    # Find the piece that moved
    moved_piece=None
    for i in range(7):
        if set(prev_occ[i]) != set(next_occ[i]):
            if moved_piece is not None:
                return False  # Multiple pieces moved
            moved_piece=i
    if moved_piece is None:
        return False  # No piece moved
    # Check if the moved piece is a valid rigid slide
    prev_cells=prev_occ[moved_piece]
    next_cells=next_occ[moved_piece]
    # The piece must have moved by exactly one cell in one direction
    # and all cells must be adjacent
    if len(prev_cells) != len(next_cells):
        return False
    # Find the displacement
    dx,dy=None,None
    for pc in prev_cells:
        if pc not in next_cells:
            # This cell is missing
            for nc in next_cells:
                if nc not in prev_cells:
                    dr,dc=divmod(nc-W*pc, W)
                    if dx is None: dx=dr; dy=dc
                    elif dx!=dr or dy!=dc: return False
    if dx is None or dy is None: return False
    # Check if displacement is valid (one cell in one direction)
    if not (abs(dx)==1 and dy==0 or dx==0 and abs(dy)==1):
        return False
    # Check if the piece fits in the new position
    h,w=dims[moved_piece]
    if moved_piece < 6:  # Non-soldier
        r,c=divmod(next_cells[0],W)
        if r<0 or c<0 or r+h>H or c+w>W: return False
    # Check if the new position is empty
    for cell in next_cells:
        if cell in [c for i in range(7) for c in prev_occ[i] if i!=moved_piece]:
            return False
    return True

def is_goal_state(state):
    # Cao Cao (C) at bottom center: rows 4-5, cols 2-3 (0-indexed)
    r,c=divmod(state[0],W)
    return r==3 and c==1 and r+2==5 and c+2==3

# Load solution
with open('/app/solution.json') as f:
    data=json.load(f)
boards=data['boards']

# Validate sequence
for i in range(len(boards)-1):
    prev_state=board_to_state(boards[i])
    next_state=board_to_state(boards[i+1])
    if not is_legal_slide(prev_state, next_state):
        print(f"Invalid slide from board {i} to {i+1}")
        exit(1)

# Validate goal
final_state=board_to_state(boards[-1])
if not is_goal_state(final_state):
    print("Final state does not meet goal condition")
    exit(1)

print("All validations passed.")
