{"path": "/app/aggregate.py", "content": "import json
from collections import defaultdict

# Initialize accumulators
user_totals = defaultdict(float)
tag_counts = defaultdict(int)

# Process each JSONL file
input_files = ["records_1.jsonl", "records_2.jsonl", "records_3.jsonl", "records_4.jsonl", "records_5.jsonl"]

for filename in input_files:
    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
                user = record["user"]
                amount = float(record["amount"])
                items = int(record["items"])
                tags = record.get("tags", [])

                # Accumulate user totals
                user_totals[user] += amount

                # Accumulate tag counts
                for tag in tags:
                    tag_counts[tag] += 1
            except Exception as e:
                print(f"Error processing line in {filename}: {e}")

# Get top 5 users by amount
sorted_users = sorted(user_totals.items(), key=lambda x: x[1], reverse=True)
top_5_users = {}
for user, total_amount in sorted_users[:5]:
    top_5_users[user] = {
        "total_amount": round(total_amount, 2),
        "total_items": int(sum(int(record["items"]) for record in [r for r in [json.loads(l) for l in open(f, 'r') if l.strip()] if r["user"] == user]))
    }

# Get top 5 tags by count
sorted_tags = sorted(tag_counts.items(), key=lambda x: x[1], reverse=True)
top_5_tags = {}
for tag, count in sorted_tags[:5]:
    top_5_tags[tag] = {"count": int(count)}

# Construct final result
result = {
    "top_5_users_by_amount": top_5_users,
    "top_5_tags_by_count": top_5_tags
}

# Write output
with open('aggregates.json', 'w') as f:
    json.dump(result, f, indent=2)

print("Aggregation complete. Output written to aggregates.json.")
"}

