{"path": "/app/check_mahjong.py", "content": "import json
from collections import Counter
from itertools import combinations

# All possible tiles
TILES = [
    # Dots
    '1D', '2D', '3D', '4D', '5D', '6D', '7D', '8D', '9D',
    # Bamboo
    '1B', '2B', '3B', '4B', '5B', '6B', '7B', '8B', '9B',
    # Characters
    '1C', '2C', '3C', '4C', '5C', '6C', '7C', '8C', '9C',
    # Honors
    'East', 'South', 'West', 'North', 'Red', 'Green', 'White'
]

# Terminal and honor tiles for Thirteen Orphans
TERMINALS = {'1D', '9D', '1B', '9B', '1C', '9C'}
HONORS = {'East', 'South', 'West', 'North', 'Red', 'Green', 'White'}
THIRTEEN_ORPHANS_TILES = TERMINALS | HONORS


def is_chow(tile1, tile2, tile3):
    """Check if three tiles form a chow (consecutive in same suit)"""
    if tile1[0] != tile2[0] or tile2[0] != tile3[0]:
        return False
    suit = tile1[0]
    nums = sorted([int(t[:-1]) for t in [tile1, tile2, tile3]])
    return nums[1] == nums[0] + 1 and nums[2] == nums[1] + 1

def can_form_pung(tiles):
    """Check if a list of 3 tiles forms a pung"""
    return len(set(tiles)) == 1

def can_form_set(tiles):
    """Check if a list of 3 tiles forms a valid set (chow or pung)"""
    if len(tiles) != 3:
        return False
    return can_form_pung(tiles) or is_chow(*tiles)

def can_form_pair(tiles):
    """Check if a list of 2 tiles forms a pair"""
    return len(tiles) == 2 and tiles[0] == tiles[1]

def is_seven_pairs(hand):
    """Check if hand can form seven pairs"""
    if len(hand) != 14:
        return False
    count = Counter(hand)
    return all(v == 2 for v in count.values())

def is_thirteen_orphans(hand):
    """Check if hand can form thirteen orphans"""
    if len(hand) != 14:
        return False
    count = Counter(hand)
    # Must have exactly one of each terminal and honor
    for tile in THIRTEEN_ORPHANS_TILES:
        if count[tile] != 1:
            return False
    # One of the tiles must appear twice
    return sum(1 for v in count.values() if v == 2) == 1

def can_form_standard(hand):
    """Check if hand can form a standard winning hand (4 sets + 1 pair)"""
    if len(hand) != 14:
        return False
    count = Counter(hand)

    # Try all possible pairs
    for tile, freq in count.items():
        if freq < 2:
            continue
        # Remove one pair
        new_count = count.copy()
        new_count[tile] -= 2
        if new_count[tile] == 0:
            del new_count[tile]

        # Try to form 4 sets from remaining 12 tiles
        if can_form_four_sets(new_count):
            return True
    return False

def can_form_four_sets(count):
    """Check if we can form 4 sets from the given tile count"""
    if sum(count.values()) != 12:
