    # Group by suit
    suits = {}
    for tile, freq in remaining.items():
        if tile[-1] in 'D' or tile[-1] in 'B' or tile[-1] in 'C':
            suit = tile[-1]
            if suit not in suits:
                suits[suit] = []
            suits[suit].append(int(tile[:-1]))

    # For each suit, try to form chows
    for suit, nums in suits.items():
        # Sort and count frequency
        num_count = Counter(nums)
        # Try to form chows
        while sum(num_count.values()) >= 3:
            # Find smallest number that can start a chow
            min_num = min(num_count.keys())
            if min_num + 1 in num_count and min_num + 2 in num_count:
                # Form a chow
                sets += 1
                num_count[min_num] -= 1
                num_count[min_num + 1] -= 1
                num_count[min_num + 2] -= 1
                if num_count[min_num] == 0:
                    del num_count[min_num]
                if num_count[min_num + 1] == 0:
                    del num_count[min_num + 1]
                if num_count[min_num + 2] == 0:
                    del num_count[min_num + 2]
            else:
                # Can't form a chow starting from min_num
                break

    return sets == 4

def check_hand(hand):
    """Check if a 13-tile hand can become a winning hand with one additional tile"""
    patterns = set()

