        # Check for Thirteen Orphans
        if is_thirteen_orphans(new_hand):
            patterns.add("Winning hand - Thirteen Orphans")

        # Check for Standard
        if can_form_standard(new_hand):
            patterns.add("Winning hand - Standard")

    if not patterns:
        patterns.add("Not a winning hand")

    return patterns

def main():
    # Process all hand files
    files = ["hand_001.json", "hand_002.json", "hand_003.json", "hand_004.json", 
             "hand_005.json", "hand_006.json", "hand_007.json", "hand_008.json"]

