import csv
import pandas as pd
from pathlib import Path
from datetime import datetime

# Field mapping: source field -> unified field
FIELD_MAP = {
    'source_a': {
        'id': 'user_id',
        'full_name': 'name',
        'email': 'email',
        'registration_date': 'created_date',
        'status': 'status'
    },
    'source_b': {
        'user_id': 'user_id',
        'name': 'name',
        'email_address': 'email',
        'created_at': 'created_date',
        'is_active': 'status'
    },
    'source_c': {
        'userId': 'user_id',
        'userName': 'name',
        'email': 'email',
        'joined': 'created_date',
        'active': 'status'
    }
}

# Priority order: A > B > C
SOURCE_PRIORITY = ['source_a', 'source_b', 'source_c']

# Output paths
OUTPUT_PARQUET = '/app/merged_users.parquet'
OUTPUT_CONFLICTS = '/app/conflicts.json'

# Read source A (JSON)
def read_source_a():
    with open('/data/source_a/users.json', 'r') as f:
        data = json.load(f)
    records = []
    for item in data:
        record = {}
        for src_field, unified_field in FIELD_MAP['source_a'].items():
            if src_field in item:
                if unified_field == 'created_date':
                    # Ensure YYYY-MM-DD format
                    date_str = item[src_field]
                    if len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-':
                        record[unified_field] = date_str
                    else:
                        # Parse and reformat
                        dt = datetime.strptime(date_str, '%Y-%m-%d')
                        record[unified_field] = dt.strftime('%Y-%m-%d')
                else:
                    record[unified_field] = item[src_field]
        records.append(record)
    return records

# Read source B (CSV)
def read_source_b():
    records = []
    with open('/data/source_b/users.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            record = {}
            for src_field, unified_field in FIELD_MAP['source_b'].items():
                if src_field in row:
                    if unified_field == 'created_date':
                        date_str = row[src_field]
                        if len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-':
                            record[unified_field] = date_str
                        else:
                            dt = datetime.strptime(date_str, '%Y-%m-%d')
                            record[unified_field] = dt.strftime('%Y-%m-%d')
                    elif unified_field == 'status':
                        # Map boolean to string
                        record[unified_field] = 'active' if row[src_field].lower() == 'true' else 'inactive'
                    else:
                        record[unified_field] = row[src_field]
            records.append(record)
    return records

# Read source C (Parquet)
def read_source_c():
    df = pd.read_parquet('/data/source_c/users.parquet')
    records = []
    for _, row in df.iterrows():
        record = {}
        for src_field, unified_field in FIELD_MAP['source_c'].items():
            if src_field in row:
                if unified_field == 'created_date':
                    date_str = str(row[src_field])
                    if len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-':
                        record[unified_field] = date_str
                    else:
                        dt = datetime.strptime(date_str, '%Y-%m-%d')
                        record[unified_field] = dt.strftime('%Y-%m-%d')
                elif unified_field == 'status':
                    record[unified_field] = 'active' if row[src_field] else 'inactive'
                else:
                    record[unified_field] = row[src_field]
        records.append(record)
    return records

# Merge records by user_id with priority
def merge_records(records_list):
    merged = {}
    conflicts = []

    # Process each source in priority order
    for source in SOURCE_PRIORITY:
        records = records_list[source]
        for record in records:
            user_id = record.get('user_id')
            if user_id is None:
                continue

            if user_id not in merged:
                merged[user_id] = {}

            # For each field, set if not already set (priority)
            for field, value in record.items():
                if field not in merged[user_id]:
                    merged[user_id][field] = value
                else:
                    # Conflict detected
                    if merged[user_id][field] != value:
                        conflict = {
                            'user_id': user_id,
                            'field': field,
                            'values': {s: None for s in SOURCE_PRIORITY},
                            'selected': merged[user_id][field]
                        }
                        # Populate values from all sources
                        for s in SOURCE_PRIORITY:
                            if s == source:
                                conflict['values'][s] = value
                            else:
                                # Look in previous sources
                                for r in records_list[s]:
                                    if r.get('user_id') == user_id:
                                        conflict['values'][s] = r.get(field)
                                        break
                        conflicts.append(conflict)

    return merged, conflicts

# Main execution
if __name__ == '__main__':
    # Read all sources
    sources = {}
    sources['source_a'] = read_source_a()
    sources['source_b'] = read_source_b()
    sources['source_c'] = read_source_c()

    # Merge with priority
    merged, conflicts = merge_records(sources)

    # Convert merged dict to list of dicts
    final_records = []
    for user_id, record in merged.items():
        # Ensure user_id is integer
        record['user_id'] = int(user_id)
        # Ensure created_date is string in YYYY-MM-DD
        if 'created_date' in record:
            # Already formatted
            pass
        else:
            # Default to empty string
            record['created_date'] = ''
        final_records.append(record)

    # Create DataFrame and write to Parquet
    df = pd.DataFrame(final_records)
    df.to_parquet(OUTPUT_PARQUET, index=False)

    # Write conflict report
    conflict_report = {
        'total_conflicts': len(conflicts),
        'conflicts': conflicts
    }
    with open(OUTPUT_CONFLICTS, 'w') as f:
        json.dump(conflict_report, f, indent=2)

    print(f'Merged {len(final_records)} users to {OUTPUT_PARQUET}')
    print(f'Generated {len(conflicts)} conflicts in {OUTPUT_CONFLICTS}')
"}

{"path": "/app/vm.js", "content": "/**
 * OpenClaw DoomGeneric MIPS Interpreter
 * Runs doomgeneric_mips and saves frames as BMP files.
 */

const fs = require('fs');
const path = require('path');

// === Configuration ===
const MEMORY_SIZE = 0x40000000; // 1 GiB
const FRAMEBUFFER_ADDR = 0x4b0a40; // From .bss section
const FRAMEBUFFER_WIDTH = 320;
const FRAMEBUFFER_HEIGHT = 200;
const FRAMEBUFFER_SIZE = FRAMEBUFFER_WIDTH * FRAMEBUFFER_HEIGHT * 4; // BGRA
const FRAME_DIR = '/tmp';
const FRAME_PREFIX = 'frame';
const FRAME_EXT = 'bmp';

// === Memory ===
const memory = new Uint8Array(MEMORY_SIZE);

// === Registers ===
const regs = new Array(32).fill(0);
const hi = { value: 0 };
const lo = { value: 0 };
const pc = { value: 0x400110 }; // Entry point

// === Coprocessor 0 (CP0) ===
const cp0 = {
  status: 0x30000000, // Initial status
  cause: 0,
  epc: 0,
  badvaddr: 0,
  count: 0,
  compare: 0
};

// === File System ===
const fileDescriptors = new Map();
const fileHandles = new Map();
const fakeFS = {
  root: {
    name: '/',
    type: 'directory',
    entries: new Map()
  }
};

// === Frame Counter ===
let frameCount = 0;

// === Helper Functions ===
function read32(addr) {
  if (addr < 0 || addr >= MEMORY_SIZE - 3) return 0;
  return (memory[addr] << 24) | (memory[addr + 1] << 16) | (memory[addr + 2] << 8) | memory[addr + 3];
}

function write32(addr, value) {
  if (addr < 0 || addr >= MEMORY_SIZE - 3) return;
  memory[addr] = (value >> 24) & 0xff;
  memory[addr + 1] = (value >> 16) & 0xff;
  memory[addr + 2] = (value >> 8) & 0xff;
  memory[addr + 3] = value & 0xff;
}

function read16(addr) {
  if (addr < 0 || addr >= MEMORY_SIZE - 1) return 0;
  return (memory[addr] << 8) | memory[addr + 1];
}

function signExtend32(value) {
  return value & 0x80000000 ? value | 0xffff0000 : value;
}

function signExtend16(value) {
  return value & 0x8000 ? value | 0xffff0000 : value;
}

function signExtend8(value) {
  return value & 0x80 ? value | 0xffffff00 : value;
}

function getRegister(name) {
  const regMap = {
    zero: 0, at: 1, v0: 2, v1: 3, a0: 4, a1: 5, a2: 6, a3: 7,
    t0: 8, t1: 9, t2: 10, t3: 11, t4: 12, t5: 13, t6: 14, t7: 15,
    s0: 16, s1: 17, s2: 18, s3: 19, s4: 20, s5: 21, s6: 22, s7: 23,
    t8: 24, t9: 25, k0: 26, k1: 27, gp: 28, sp: 29, s8: 30, ra: 31
  };
  return regMap[name] || 0;
}

function setRegister(name, value) {
  const reg = getRegister(name);
  regs[reg] = value;
}

function getRegisterValue(name) {
  return regs[getRegister(name)];
}

function setRegisterValue(name, value) {
  regs[getRegister(name)] = value;
}

// === Syscall Handlers ===
function handleSyscall() {
  const syscallNum = getRegisterValue('v0');
  const arg1 = getRegisterValue('a0');
  const arg2 = getRegisterValue('a1');
  const arg3 = getRegisterValue('a2');
  const arg4 = getRegisterValue('a3');
  const arg5 = getRegisterValue('t0');
  const arg6 = getRegisterValue('t1');

  let result = 0;
  let errno = 0;

  switch (syscallNum) {
    case 0: // read
      result = sys_read(arg1, arg2, arg3);
      break;
    case 1: // write
      result = sys_write(arg1, arg2, arg3);
      break;
    case 2: // open
      result = sys_open(arg1, arg2, arg3);
      break;
    case 3: // close
      result = sys_close(arg1);
      break;
    case 8: // lseek
      result = sys_lseek(arg1, arg2, arg3);
      break;
    case 74: // fsync
      result = sys_fsync(arg1);
      break;
    case 82: // rename
      result = sys_rename(arg1, arg2);
      break;
    case 83: // mkdir
      result = sys_mkdir(arg1, arg2);
      break;
    case 87: // unlink
      result = sys_unlink(arg1);
      break;
    case 100: // exit
      console.log('Doom exited with code:', arg1);
      process.exit(arg1);
      break;
    default:
      console.warn(`Unknown syscall: ${syscallNum}`);
      result = -1;
      errno = 34; // EIO
  }

  if (result < 0) {
    setRegisterValue('v0', -result);
    setRegisterValue('v1', errno);
  } else {
    setRegisterValue('v0', result);
  }
}

// === File System ===
function sys_read(fd, buf, count) {
  const handle = fileHandles.get(fd);
  if (!handle) return -1;

  const data = handle.read(count);
  if (data === null) return -1;

  for (let i = 0; i < data.length; i++) {
    write32(buf + i, data[i]);
  }

  return data.length;
}

function sys_write(fd, buf, count) {
  const handle = fileHandles.get(fd);
  if (!handle) return -1;

  let data = new Uint8Array(count);
  for (let i = 0; i < count; i++) {
    data[i] = read32(buf + i);
  }

  const written = handle.write(data);
  return written;
}

function sys_open(pathPtr, flags, mode) {
  const path = readCString(pathPtr);
  if (!path) return -1;

  const handle = new FakeFileHandle(path, flags, mode);
  const fd = fileDescriptors.size;
  fileDescriptors.set(fd, handle);
  fileHandles.set(fd, handle);

  return fd;
}

function sys_close(fd) {
  const handle = fileHandles.get(fd);
  if (!handle) return -1;

  handle.close();
  fileHandles.delete(fd);
  fileDescriptors.delete(fd);

  return 0;
}

function sys_lseek(fd, offset, whence) {
  const handle = fileHandles.get(fd);
  if (!handle) return -1;

  return handle.lseek(offset, whence);
}

function sys_fsync(fd) {
  const handle = fileHandles.get(fd);
  if (!handle) return -1;

  handle.fsync();
  return 0;
}

function sys_rename(oldPathPtr, newPathPtr) {
  const oldPath = readCString(oldPathPtr);
  const newPath = readCString(newPathPtr);
  if (!oldPath || !newPath) return -1;

  const oldNode = findNode(oldPath);
  if (!oldNode) return -1;

  const parent = findParent(newPath);
  if (!parent) return -1;

  const name = path.basename(newPath);
  const newNode = createNode(name, oldNode.type, parent);

  if (oldNode.type === 'file') {
    newNode.data = oldNode.data;
  }

  parent.entries.set(name, newNode);
  oldNode.parent.entries.delete(oldNode.name);

  return 0;
}

function sys_mkdir(pathPtr, mode) {
  const path = readCString(pathPtr);
  if (!path) return -1;

  const parent = findParent(path);
  if (!parent) return -1;

  const name = path.basename(path);
  const node = createNode(name, 'directory', parent);

  parent.entries.set(name, node);

  return 0;
}

function sys_unlink(pathPtr) {
  const path = readCString(pathPtr);
  if (!path) return -1;

  const parent = findParent(path);
  if (!parent) return -1;

  const name = path.basename(path);
  const node = parent.entries.get(name);
  if (!node) return -1;

  parent.entries.delete(name);

  return 0;
}

// === Helper for Fake File System ===
function readCString(ptr) {
  let str = '';
  let i = 0;
  while (true) {
    const c = memory[ptr + i];
    if (c === 0) break;
    str += String.fromCharCode(c);
    i++;
  }
  return str;
}

function findNode(path) {
  const parts = path.split('/').filter(p => p);
  let node = fakeFS.root;

  for (const part of parts) {
    if (node.type !== 'directory') return null;
    const child = node.entries.get(part);
    if (!child) return null;
    node = child;
  }

  return node;
}

function findParent(path) {
  const parts = path.split('/').filter(p => p);
  if (parts.length === 0) return null;

  let node = fakeFS.root;
  for (let i = 0; i < parts.length - 1; i++) {
    if (node.type !== 'directory') return null;
    const child = node.entries.get(parts[i]);
    if (!child) return null;
    node = child;
  }

  return node;
}

function createNode(name, type, parent) {
  const node = {
    name,
    type,
    parent,
    entries: new Map(),
    data: null
  };

  if (type === 'file') {
    node.data = new Uint8Array(0);
  }

  return node;
}

// === Fake File Handle ===
class FakeFileHandle {
  constructor(path, flags, mode) {
    this.path = path;
    this.flags = flags;
    this.mode = mode;
    this.pos = 0;
    this.size = 0;
    this.data = new Uint8Array(0);

    // Initialize with doom.wad
    if (path === '/doom.wad') {
      this.data = fs.readFileSync('/app/doom.wad');
      this.size = this.data.length;
    }
  }

  read(count) {
    if (this.pos >= this.size) return null;

    const end = Math.min(this.pos + count, this.size);
    const data = this.data.slice(this.pos, end);
    this.pos = end;

    return data;
  }

  write(data) {
    const start = this.pos;
    const end = start + data.length;

    if (end > this.size) {
      const newBuf = new Uint8Array(end);
      newBuf.set(this.data);
      this.data = newBuf;
      this.size = end;
    }

    this.data.set(data, start);
    this.pos = end;

    return data.length;
  }

  lseek(offset, whence) {
    switch (whence) {
      case 0: // SEEK_SET
        this.pos = offset;
        break;
      case 1: // SEEK_CUR
        this.pos += offset;
        break;
      case 2: // SEEK_END
        this.pos = this.size + offset;
        break;
      default:
        return -1;
    }

    if (this.pos < 0) this.pos = 0;
    if (this.pos > this.size) this.pos = this.size;

    return this.pos;
  }

  fsync() {
    // No-op
  }

  close() {
    // No-op
  }
}

// === Frame Output ===
function saveFrame() {
  const frameData = new Uint8Array(FRAMEBUFFER_SIZE);
  const fbAddr = FRAMEBUFFER_ADDR;

  for (let i = 0; i < FRAMEBUFFER_SIZE; i += 4) {
    const pixel = read32(fbAddr + i);
    frameData[i] = (pixel >> 16) & 0xff; // B
    frameData[i + 1] = (pixel >> 8) & 0xff;  // G
    frameData[i + 2] = pixel & 0xff;       // R
    frameData[i + 3] = (pixel >> 24) & 0xff; // A
  }

  const filename = path.join(FRAME_DIR, `${FRAME_PREFIX}${frameCount}.${FRAME_EXT}`);
  const header = new Uint8Array(54);
  header[0] = 0x42; // 'B'
  header[1] = 0x4d; // 'M'
  const fileSize = 54 + FRAMEBUFFER_SIZE;
  header[2] = fileSize & 0xff;
  header[3] = (fileSize >> 8) & 0xff;
  header[4] = (fileSize >> 16) & 0xff;
  header[5] = (fileSize >> 24) & 0xff;
  header[10] = 54;
  header[14] = 40;
  header[18] = FRAMEBUFFER_WIDTH & 0xff;
  header[19] = (FRAMEBUFFER_WIDTH >> 8) & 0xff;
  header[20] = (FRAMEBUFFER_WIDTH >> 16) & 0xff;
  header[21] = (FRAMEBUFFER_WIDTH >> 24) & 0xff;
  header[22] = FRAMEBUFFER_HEIGHT & 0xff;
  header[23] = (FRAMEBUFFER_HEIGHT >> 8) & 0xff;
  header[24] = (FRAMEBUFFER_HEIGHT >> 16) & 0xff;
  header[25] = (FRAMEBUFFER_HEIGHT >> 24) & 0xff;
  header[26] = 1;
  header[28] = 32;
  header[34] = FRAMEBUFFER_SIZE & 0xff;
  header[35] = (FRAMEBUFFER_SIZE >> 8) & 0xff;
  header[36] = (FRAMEBUFFER_SIZE >> 16) & 0xff;
  header[37] = (FRAMEBUFFER_SIZE >> 24) & 0xff;

  const buffer = new Uint8Array(header.length + frameData.length);
  buffer.set(header);
  buffer.set(frameData, header.length);

  fs.writeFileSync(filename, buffer);
  console.log(`Frame saved: ${filename}`);
  frameCount++;
}

// === Instruction Decoder ===
function decodeInstruction(inst) {
  const op = (inst >> 26) & 0x3f;
  const rs = (inst >> 21) & 0x1f;
  const rt = (inst >> 16) & 0x1f;
  const rd = (inst >> 11) & 0x1f;
  const shamt = (inst >> 6) & 0x1f;
  const funct = inst & 0x3f;

  return { op, rs, rt, rd, shamt, funct };
}

function executeInstruction(inst) {
  const { op, rs, rt, rd, shamt, funct } = decodeInstruction(inst);

  switch (op) {
    case 0: // R-type
      switch (funct) {
        case 0: // sll
          setRegisterValue('rd', (getRegisterValue('rt') << shamt) & 0xffffffff);
          break;
        case 2: // srl
          setRegisterValue('rd', (getRegisterValue('rt') >>> shamt) & 0xffffffff);
          break;
        case 3: // sra
          setRegisterValue('rd', getRegisterValue('rt') >> shamt);
          break;
        case 4: // sllv
          setRegisterValue('rd', (getRegisterValue('rt') << getRegisterValue('rs')) & 0xffffffff);
          break;
        case 6: // srlv
          setRegisterValue('rd', (getRegisterValue('rt') >>> getRegisterValue('rs')) & 0xffffffff);
          break;
        case 7: // srav
          setRegisterValue('rd', getRegisterValue('rt') >> getRegisterValue('rs'));
          break;
        case 8: // jr
          pc.value = getRegisterValue('rs');
          return;
        case 9: // jalr
          setRegisterValue('rd', pc.value + 8);
          pc.value = getRegisterValue('rs');
          return;
        case 12: // syscall
          handleSyscall();
          pc.value += 4;
          return;
        case 13: // break
          console.log('Break instruction encountered');
          process.exit(1);
        case 16: // mfhi
          setRegisterValue('rd', hi.value);
          break;
        case 17: // mthi
          hi.value = getRegisterValue('rs');
          break;
        case 18: // mflo
          setRegisterValue('rd', lo.value);
          break;
        case 19: // mtlo
          lo.value = getRegisterValue('rs');
          break;
        case 24: // mult
          const mult = getRegisterValue('rs') * getRegisterValue('rt');
          hi.value = (mult >> 32) & 0xffffffff;
          lo.value = mult & 0xffffffff;
          break;
        case 25: // multu
          const multu = (getRegisterValue('rs') >>> 0) * (getRegisterValue('rt') >>> 0);
          hi.value = (multu >> 32) & 0xffffffff;
          lo.value = multu & 0xffffffff;
          break;
        case 26: // div
          const div = getRegisterValue('rs') / getRegisterValue('rt');
          lo.value = Math.floor(div) & 0xffffffff;
          hi.value = (getRegisterValue('rs') % getRegisterValue('rt')) & 0xffffffff;
          break;
        case 27: // divu
          const divu = (getRegisterValue('rs') >>> 0) / (getRegisterValue('rt') >>> 0);
          lo.value = Math.floor(divu) & 0xffffffff;
          hi.value = ((getRegisterValue('rs') >>> 0) % (getRegisterValue('rt') >>> 0)) & 0xffffffff;
          break;
        case 32: // add
          setRegisterValue('rd', (getRegisterValue('rs') + getRegisterValue('rt')) & 0xffffffff);
          break;
        case 33: // addu
          setRegisterValue('rd', (getRegisterValue('rs') + getRegisterValue('rt')) & 0xffffffff);
          break;
        case 34: // sub
          setRegisterValue('rd', (getRegisterValue('rs') - getRegisterValue('rt')) & 0xffffffff);
          break;
        case 35: // subu
          setRegisterValue('rd', (getRegisterValue('rs') - getRegisterValue('rt')) & 0xffffffff);
          break;
        case 36: // and
          setRegisterValue('rd', getRegisterValue('rs') & getRegisterValue('rt'));
          break;
        case 37: // or
          setRegisterValue('rd', getRegisterValue('rs') | getRegisterValue('rt'));
          break;
        case 38: // xor
          setRegisterValue('rd', getRegisterValue('rs') ^ getRegisterValue('rt'));
          break;
        case 39: // nor
          setRegisterValue('rd', ~(getRegisterValue('rs') | getRegisterValue('rt')) & 0xffffffff);
          break;
        case 42: // slt
          setRegisterValue('rd', getRegisterValue('rs') < getRegisterValue('rt') ? 1 : 0);
          break;
        case 43: // sltu
          setRegisterValue('rd', (getRegisterValue('rs') >>> 0) < (getRegisterValue('rt') >>> 0) ? 1 : 0);
          break;
        default:
          console.warn(`Unknown R-type funct: ${funct}`);
      }
      break;

    case 1: // special
      switch (funct) {
        case 0: // tlbwi
          // Not implemented
          break;
        case 1: // tlbwr
