function run() {
  // Load the ELF into memory
  const elfData = fs.readFileSync('/app/doomgeneric_mips');
  const textSection = elfData.slice(0x110, 0x110 + 0x3dbd0);
  const rodataSection = elfData.slice(0x3dce0, 0x3dce0 + 0x18834);
  const dataSection = elfData.slice(0x56520, 0x56520 + 0x0eb80);

  // Copy sections into memory
  memory.set(textSection, 0x400110);
  memory.set(rodataSection, 0x43dce0);
  memory.set(dataSection, 0x466520);

  // Initialize registers
  setRegisterValue('ra', 0);
  setRegisterValue('sp', 0x4750c0 + 0x4003c6d0 - 16);
  setRegisterValue('gp', 0x4750c0);
  setRegisterValue('s8', 0x4750c0);

  // Initialize fake filesystem
  const wadNode = createNode('doom.wad', 'file', fakeFS.root);
  wadNode.data = fs.readFileSync('/app/doom.wad');
  fakeFS.root.entries.set('doom.wad', wadNode);

  // Initialize framebuffer
  const fbAddr = FRAMEBUFFER_ADDR;
  for (let i = 0; i < FRAMEBUFFER_SIZE; i += 4) {
    write32(fbAddr + i, 0x00000000);
  }

  // Main execution loop
  let cycles = 0;
  const maxCycles = 100000000; // Prevent infinite loop

  while (cycles < maxCycles) {
    const inst = read32(pc.value);
    executeInstruction(inst);

    // Check for frame save
    if (frameCount === 0 && pc.value === 0x400124) {
      saveFrame();
    }

    cycles++;
  }

  console.log('Execution completed after', cycles, 'cycles');
}

// === Start ===
run();
"}

