#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv)
{
    options_t o;
    if (!parse_options(argc, argv, &o, 0, "/app/serial.txt", "/app/serial_summary.txt"))
        return EXIT_FAILURE;

    particle_t *p = (particle_t *)malloc((size_t)o.n * sizeof(particle_t));
    if (!p) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }

    double size = initialize_particles(p, o.n, NULL);
    bins_t b;
    bins_create(&b, o.n, size, 0.0);

    double t0 = wall_time();
    for (int step = 0; step < NSTEPS; ++step) {
        bins_rebuild(&b, p, o.n);
        for (int i = 0; i < o.n; ++i) {
            stats_t s = {1.0, 0.0, 0};
            force_on(i, p, &b, 1.30 * size / (double)(int)ceil(sqrt((double)o.n)), &s);
            move_particle(&p[i], size);
        }
    }
    double t1 = wall_time();

    double absmin, absavg;
    stats_t s = {1.0, 0.0, 0};
    for (int i = 0; i < o.n; ++i) {
        stats_t t = {1.0, 0.0, 0};
        force_on(i, p, &b, 1.30 * size / (double)(int)ceil(sqrt((double)o.n), &t);
        if (t.min_ratio < s.min_ratio) s.min_ratio = t.min_ratio;
        s.ratio_sum += t.ratio_sum;
        s.count += t.count;
    }
    final_metrics(&s, &absmin, &absavg);

    printf("n = %d, simulation time = %.6f seconds\n", o.n, t1 - t0);
    printf("absmin = %.6f\n", absmin);
    printf("absavg = %.6f\n", absavg);

    if (!write_positions(o.output, p, o.n, size))
        return EXIT_FAILURE;

    FILE *f = fopen(o.summary, "w");
    if (!f) { perror(o.summary); return EXIT_FAILURE; }
    fprintf(f, "%d %.6f\n", o.n, t1 - t0);
    if (fclose(f)) { perror(o.summary); return EXIT_FAILURE; }

    free(p);
    bins_destroy(&b);
    return EXIT_SUCCESS;
}"}

