#include <stdlib.h>
#include <math.h>

// Constants
#define WIDTH 2400
#define HEIGHT 1800
#define MAX_DEPTH 5

// Vector struct
typedef struct { double x, y, z; } vec3;

// Ray struct
typedef struct { vec3 origin, direction; } ray;

// Sphere struct
typedef struct { vec3 center; double radius; } sphere;

// Plane struct
typedef struct { vec3 normal, point; } plane;

// Color struct
typedef struct { double r, g, b; } color;

// Utility functions
vec3 vec3_add(vec3 a, vec3 b) { return (vec3){a.x + b.x, a.y + b.y, a.z + b.z}; }
vec3 vec3_sub(vec3 a, vec3 b) { return (vec3){a.x - b.x, a.y - b.y, a.z - b.z}; }
vec3 vec3_mul(vec3 a, double s) { return (vec3){a.x * s, a.y * s, a.z * s}; }
vec3 vec3_div(vec3 a, double s) { return (vec3){a.x / s, a.y / s, a.z / s}; }
vec3 vec3_scale(vec3 a, vec3 b) { return (vec3){a.x * b.x, a.y * b.y, a.z * b.z}; }

// Dot product
double dot(vec3 a, vec3 b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

// Length squared
double length_sq(vec3 a) { return a.x * a.x + a.y * a.y + a.z * a.z; }

// Length
double length(vec3 a) { return sqrt(length_sq(a)); }

// Normalize
vec3 normalize(vec3 a) { return vec3_div(a, length(a)); }

// Ray-sphere intersection
int intersect_sphere(ray r, sphere s, double *t) {
    vec3 oc = vec3_sub(r.origin, s.center);
    double a = dot(r.direction, r.direction);
    double b = 2.0 * dot(oc, r.direction);
    double c = dot(oc, oc) - s.radius * s.radius;
    double discriminant = b * b - 4 * a * c;
    if (discriminant < 0) return 0;
    double sqrt_disc = sqrt(discriminant);
    double t1 = (-b - sqrt_disc) / (2 * a);
    double t2 = (-b + sqrt_disc) / (2 * a);
    if (t1 > 0) { *t = t1; return 1; }
    if (t2 > 0) { *t = t2; return 1; }
    return 0;
}

// Ray-plane intersection
int intersect_plane(ray r, plane p, double *t) {
    double denom = dot(p.normal, r.direction);
    if (fabs(denom) < 1e-8) return 0;
    vec3 oc = vec3_sub(r.origin, p.point);
    *t = -dot(oc, p.normal) / denom;
    return *t > 0;
}

// Check if point is on checkerboard
int is_checker(vec3 p) {
    int x = (int)(p.x / 100.0) % 2;
    int z = (int)(p.z / 100.0) % 2;
    return (x + z) % 2;
}

// Get color from point on checkerboard
color get_checker_color(vec3 p) {
    return is_checker(p) ? (color){0.25, 0.25, 0.25} : (color){0.6, 0.6, 0.6};
}

// Get sky color
color get_sky_color(vec3 dir) {
    double t = (dir.y + 1.0) * 0.5;
    return (color){
        159 + (187 - 159) * t,
        197 + (215 - 197) * t,
        255
    };
}

// Get sphere color
color get_sphere_color(vec3 p) {
    double t = (p.y - 850.0) / 350.0;
    if (t < 0) t = 0;
    if (t > 1) t = 1;
    return (color){
        107 + (187 - 107) * t,
        21 + (215 - 21) * t,
        21 + (255 - 21) * t
    };
}

// Shade
color shade(ray r, sphere s, plane p, double t) {
    vec3 hit_point = vec3_add(r.origin, vec3_mul(r.direction, t));
    vec3 normal = normalize(vec3_sub(hit_point, s.center));
    vec3 light_dir = normalize((vec3){0.0, -1.0, -1.0});
    double NdotL = dot(normal, light_dir);
    if (NdotL < 0) NdotL = 0;
    color base_color = get_sphere_color(hit_point);
    color shaded = (color){
        base_color.r * NdotL,
        base_color.g * NdotL,
        base_color.b * NdotL
    };
    return shaded;
}

// Ray trace
color trace_ray(ray r, sphere s, plane p, int depth) {
    double t;
    if (depth <= 0) return (color){0.0, 0.0, 0.0};
    if (intersect_sphere(r, s, &t)) {
        return shade(r, s, p, t);
    }
    if (intersect_plane(r, p, &t)) {
        vec3 hit_point = vec3_add(r.origin, vec3_mul(r.direction, t));
        return get_checker_color(hit_point);
    }
    return get_sky_color(r.direction);
}

// Main
int main() {
    FILE *fp = fopen("reconstructed.ppm", "wb");
    if (!fp) return 1;
    fprintf(fp, "P6\n%d %d\n255\n", WIDTH, HEIGHT);
    sphere s = {{1200.0, 850.0, 1000.0}, 350.0};
    plane p = {{0.0, 1.0, 0.0}, {0.0, 900.0, 0.0}};
    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            double u = (double)x / WIDTH;
            double v = (double)y / HEIGHT;
            vec3 origin = {0.0, 0.0, 0.0};
            vec3 direction = normalize((vec3){
                (2.0 * u - 1.0) * 1.0,
                (1.0 - 2.0 * v) * 1.0,
                -1.0
            });
            ray r = {origin, direction};
            color c = trace_ray(r, s, p, MAX_DEPTH);
            unsigned char r8 = (unsigned char)(c.r * 255);
            unsigned char g8 = (unsigned char)(c.g * 255);
            unsigned char b8 = (unsigned char)(c.b * 255);
            fputc(r8, fp);
            fputc(g8, fp);
            fputc(b8, fp);
        }
    }
    fclose(fp);
    return 0;
}"}

