/*
# Python code starts here
*/

# Function to compute Fibonacci number

def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Main execution
if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python3 main.py.c N")
        sys.exit(1)

    try:
        n = int(sys.argv[1])
        if n < 0:
            print("Error: N must be non-negative")
            sys.exit(1)

        result = fibonacci(n)
        print(result)
    except ValueError:
        print("Error: N must be an integer")
        sys.exit(1)

/*
C code starts here
*/

int fibonacci(int n) {
    if (n <= 1) {
        return n;
    }
    int a = 0, b = 1;
    for (int i = 2; i <= n; i++) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s N\n", argv[0]);
        return 1;
    }

    int n = atoi(argv[1]);
    if (n < 0) {
        fprintf(stderr, "Error: N must be non-negative\n");
        return 1;
    }

    int result = fibonacci(n);
    printf("%d\n", result);
    return 0;
}
