{"path": "/app/rs/src/packet_enumerator.rs", "content": "use crate::lzma_packet::LZMAPacket;
use crate::lzma_state::LZMAState;
use crate::substring_enumerator::SubstringEnumerator;

pub struct PacketEnumerator<'a> {
    data: &'a [u8],
    substring_enumerator: SubstringEnumerator<'a>,
}

impl<'a> PacketEnumerator<'a> {
    pub fn memory_usage(data_size: usize) -> usize {
        std::mem::size_of::<Self>().saturating_add(SubstringEnumerator::memory_usage(data_size))
    }

    pub fn new(data: &[u8]) -> Self {
        Self { data, substring_enumerator: SubstringEnumerator::new(data, 2, 273) }
    }

    pub fn for_each<F>(&self, state: &LZMAState, mut callback: F)
    where F: FnMut(&LZMAState, LZMAPacket),
    {
        callback(state, LZMAPacket::literal_packet());
        if state.position > 0 {
            let rep0_pos = state.position - state.dists[0] - 1;
            if self.data[state.position] == self.data[rep0_pos] {
                callback(state, LZMAPacket::short_rep_packet());
            }
        }
        self.substring_enumerator.for_each(state.position, |offset, length| {
            callback(state, LZMAPacket::match_packet(state.position - offset - 1, length as u32));
            for i in 0..4 {
                if state.dists[i] == state.position - offset - 1 {
                    callback(state, LZMAPacket::long_rep_packet(i as u32, length as u32));
                }
            }
        });
    }
}
"}

