#include <stdlib.h>
#include <string.h>

/*
 * Polyglot: Python/C Fibonacci Calculator
 * 
 * This file is valid Python and C code.
 * Python: runs with `python3 main.py.c N`
 * C: compiles with `gcc main.py.c -o cmain && ./cmain N`
 * 
 * The C section uses a simple arbitrary-precision integer implementation
 * to handle large Fibonacci numbers.
 */

/*
 * Python-compatible C preprocessor block
 * This section is ignored by Python but compiled by C
 */

#ifdef __C__

/* Arbitrary-precision integer structure */
typedef struct {
    int *digits;
    int size;
    int capacity;
} BigInt;

/* Initialize a BigInt */
void init(BigInt *b) {
    b->digits = (int*)calloc(1, sizeof(int));
    b->size = 1;
    b->capacity = 1;
}

/* Free a BigInt */
void free(BigInt *b) {
    free(b->digits);
}

/* Copy a BigInt */
void copy(BigInt *dst, BigInt *src) {
    dst->size = src->size;
    if (dst->capacity < src->capacity) {
        dst->digits = (int*)realloc(dst->digits, src->capacity * sizeof(int));
        dst->capacity = src->capacity;
    }
    memcpy(dst->digits, src->digits, src->size * sizeof(int));
}

/* Add two BigInts */
void add(BigInt *r, BigInt *a, BigInt *b) {
    int carry = 0;
    int max_size = (a->size > b->size) ? a->size : b->size;

    if (r->capacity < max_size + 1) {
        r->digits = (int*)realloc(r->digits, (max_size + 1) * sizeof(int));
        r->capacity = max_size + 1;
    }

    for (int i = 0; i < max_size || carry; i++) {
        int d1 = (i < a->size) ? a->digits[i] : 0;
        int d2 = (i < b->size) ? b->digits[i] : 0;
        int sum = d1 + d2 + carry;
        r->digits[i] = sum % 10;
        carry = sum / 10;
    }

    r->size = (carry) ? max_size + 1 : max_size;
}

/* Print a BigInt */
void print(BigInt *b) {
    for (int i = b->size - 1; i >= 0; i--) {
        printf("%d", b->digits[i]);
    }
    printf("\n");
}

/* Compute Fibonacci number using arbitrary-precision integers */
void fib(int n) {
    if (n == 0) {
        printf("0\n");
        return;
    }
    if (n == 1) {
        printf("1\n");
        return;
    }

    BigInt a, b, temp;
    init(&a);
    init(&b);
    init(&temp);

    a.digits[0] = 0;
    b.digits[0] = 1;

    for (int i = 2; i <= n; i++) {
        add(&temp, &a, &b);
        copy(&a, &b);
        copy(&b, &temp);
    }

    print(&b);

    free(&a);
    free(&b);
    free(&temp);
}

