    rope_project = workspace._rope_project_builder(rope_config)

    rename = Rename(
        rope_project,
        libutils.path_to_resource(rope_project, document.path),
        document.offset_at_position(position),
    )

    log.debug(
        "Executing rename of %s to %s", document.word_at_position(position), new_name
    )
    changeset = rename.get_changes(new_name, in_hierarchy=True, docs=True)
    log.debug("Finished rename: %s", changeset.changes)
    changes = []
    for change in changeset.changes:
        uri = uris.from_fs_path(change.resource.path)
        doc = workspace.get_maybe_document(uri)
        # Use the original document content to compute the range end,
        # since the range describes what to replace in the original document.
        if doc is not None:
            old_source = doc.source
        else:
            with open(str(change.resource.path), "r", encoding="utf-8") as f:
                old_source = f.read()
        changes.append(
            {
                "textDocument": {"uri": uri, "version": doc.version if doc else None},
                "edits": [
                    {
                        "range": {
                            "start": {"line": 0, "character": 0},
                            "end": _get_document_end(old_source),
                        },
                        "newText": change.new_contents,
                    }
                ],
            }
        )
    return {"documentChanges": changes}


def _get_document_end(source):
    """Return the end position of the given document source as a
    LSP position dict ``{"line": ..., "character": ...}``.

    Handles documents that do not end with a trailing newline by
    returning the position at the end of the last line rather than
    pointing to a non-existent line.
    """
    lines = source.splitlines(True)
    if not lines:
        return {"line": 0, "character": 0}
    last_line = lines[-1]
    if last_line.endswith("\n") or last_line.endswith("\r"):
        return {"line": len(lines), "character": 0}
    return {"line": len(lines) - 1, "character": len(last_line)}"}

