import itertools
from collections import defaultdict

# Parse WCNF file
def parse_wcnf(path):
    clauses = []
    soft_clauses = []
    nvars = 0
    ncls = 0

    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('c'):
                continue
            if line.startswith('p'):
                parts = line.split()
                nvars = int(parts[2])
                ncls = int(parts[3])
                continue
            if line.startswith('h'):
                # Hard clause
                clause = [int(x) for x in line.split()[1:-1]]
                clauses.append(clause)
            else:
                # Soft clause
                parts = line.split()
                weight = int(parts[0])
                clause = [int(x) for x in parts[1:-1]]
                soft_clauses.append((weight, clause))

    return clauses, soft_clauses, nvars

# Simple SAT solver for hard clauses
def solve_hard(clauses, nvars):
    # Use a simple greedy assignment with backtracking
    # We'll use a simple iterative improvement
    assignment = [0] * (nvars + 1)  # 0: unassigned, 1: true, -1: false
    satisfied = [False] * len(clauses)

    # Try to satisfy all hard clauses
    while True:
        changes = False
        for i, clause in enumerate(clauses):
            if satisfied[i]:
                continue
            # Check if clause is satisfied
            sat = False
            for lit in clause:
                if lit > 0 and assignment[lit] == 1:
                    sat = True
                elif lit < 0 and assignment[-lit] == -1:
                    sat = True
            if sat:
                satisfied[i] = True
                continue

            # If not satisfied, pick a literal to assign
            # Prefer unassigned literals
            unassigned = []
            for lit in clause:
                var = abs(lit)
                if assignment[var] == 0:
                    unassigned.append(lit)
            if unassigned:
                # Assign first unassigned literal
                lit = unassigned[0]
                var = abs(lit)
                assignment[var] = 1 if lit > 0 else -1
                changes = True
            else:
                # All literals assigned, but clause not satisfied
                # Try flipping one literal
                for lit in clause:
                    var = abs(lit)
                    if assignment[var] == 1:
                        assignment[var] = -1
                        changes = True
                        break
                    elif assignment[var] == -1:
                        assignment[var] = 1
                        changes = True
                        break
        if not changes:
            break

    # Check if all hard clauses are satisfied
    for i, clause in enumerate(clauses):
        sat = False
        for lit in clause:
            if lit > 0 and assignment[lit] == 1:
                sat = True
            elif lit < 0 and assignment[-lit] == -1:
                sat = True
        if not sat:
            return None  # Unsatisfiable

    return assignment

# Maximize soft clause satisfaction
def maximize_soft(soft_clauses, assignment):
    total_weight = 0
    for weight, clause in soft_clauses:
        sat = False
        for lit in clause:
            if lit > 0 and assignment[lit] == 1:
                sat = True
            elif lit < 0 and assignment[-lit] == -1:
                sat = True
        if sat:
            total_weight += weight
    return total_weight

# Main solver
def main():
    if len(sys.argv) != 2:
        print('Usage: python3 solver.py <wcnc_file>')
        sys.exit(1)

    wcnf_path = sys.argv[1]
    clauses, soft_clauses, nvars = parse_wcnf(wcnf_path)

    # Solve hard constraints
    assignment = solve_hard(clauses, nvars)
    if assignment is None:
        print('UNSAT', file=sys.stderr)
        sys.exit(1)

    # Maximize soft clause satisfaction
    max_weight = maximize_soft(soft_clauses, assignment)
    print(max_weight)

if __name__ == '__main__':
    main()
"}

